import {createContext,useContext,useEffect,useRef,useState} from 'react'
import type {ReactNode} from 'react'
import type {Course,Lecture,Task} from './model'
import {assetUrl} from './model'
import {read,save} from './storage'
import {evaluate} from './scoring'
import type {Answer,Key,Result} from './scoring'
import {Modal} from './Modal'
export type Attempt={draft:Answer;submitted?:Answer;result?:Result;seed:number;attempts:number;reveal?:boolean}
type Context={readonly?:boolean;reveal:(t:Task,value:boolean)=>void;attempts:Record<string,Attempt>;change:(t:Task,a:Answer)=>void;submit:(t:Task)=>Promise<void>;retry:(t:Task)=>void;busy:string;error:string;keys:Record<string,Key>;reset:()=>void}
const AssessmentContext=createContext<Context|null>(null)
const fresh=(t:Task):Attempt=>({draft:t.type==='matching'?{}:t.type==='short'?'':[],seed:crypto.getRandomValues(new Uint32Array(1))[0],attempts:0})
export function AssessmentProvider({course,base,children,snapshot,readonly=false}:{course:Course;base:string;children:ReactNode;snapshot?:Record<string,Attempt>;readonly?:boolean}){
 const storageKey=`lecture:${base}:${course.id}:${course.contentVersion}:attempts`
 const [attempts,setAttempts]=useState<Record<string,Attempt>>(()=>read(storageKey,{}));const [keys,setKeys]=useState<Record<string,Key>>({});const [busy,setBusy]=useState('');const [error,setError]=useState('');const request=useRef<Promise<Record<string,Key>>|null>(null)
 const put=(id:string,value:Attempt)=>setAttempts(old=>{const next={...old,[id]:value};if(!save(storageKey,next))setError('Не удалось сохранить попытку на устройстве.');return next})
 const load=async()=>{if(!course.assessment)throw Error('Банк самопроверки не подключён');if(!request.current)request.current=fetch(assetUrl(course.assessment.url,base)).then(r=>{if(!r.ok)throw Error('Не удалось загрузить банк ответов');return r.json()}).then(data=>{if(data.courseId!==course.id||data.contentVersion!==course.contentVersion||!data.keys)throw Error('Версия ключей не соответствует лекции');setKeys(data.keys);return data.keys}).catch(e=>{request.current=null;throw e});return request.current}
 const submit=async(t:Task)=>{const a=attempts[t.id]||fresh(t);const draft=a.draft;if((typeof draft==='string'&&!draft.trim())||(Array.isArray(draft)&&!draft.length)||(typeof draft==='object'&&!Array.isArray(draft)&&!Object.values(draft).some(Boolean))){setError('Сначала введите ответ. Пустое поле не считается попыткой.');return}setError('');setBusy(t.id);try{const bank=await load();if(!bank[t.id])throw Error('Не найден ключ задания');const result=evaluate(t,bank[t.id],draft);put(t.id,{...a,submitted:structuredClone(draft),result,attempts:a.attempts+1})}catch(e){setError(String(e))}finally{setBusy('')}}
 return <AssessmentContext.Provider value={{attempts:readonly?(snapshot||{}):attempts,readonly,reveal:(t,value)=>{const a=attempts[t.id];if(a?.result)put(t.id,{...a,reveal:value})},change:(t,a)=>{setError('');put(t.id,{...(attempts[t.id]||fresh(t)),draft:a})},submit,retry:t=>{setError('');const a=attempts[t.id]||fresh(t);put(t.id,{...fresh(t),attempts:a.attempts})},busy,error,keys,reset:()=>{setAttempts({});save(storageKey,{});setError('')}}}>{children}</AssessmentContext.Provider>
}
export function TaskView({task:t}:{task:Task}){
 const ctx=useContext(AssessmentContext)!;const a=ctx.attempts[t.id];const options=t.options||[];const done=Boolean(a?.result);const show=Boolean(a?.reveal);const disabled=done||ctx.readonly
 const choice=(id:string)=>{if(t.type==='single')ctx.change(t,[id]);else{const list=Array.isArray(a?.draft)?a.draft:[];ctx.change(t,list.includes(id)?list.filter(x=>x!==id):[...list,id])}}
 return <section className="interactive-task"><p className="task-prompt">{t.prompt}</p>
 {(t.type==='single'||t.type==='multiple')&&<div className="choice-grid" tabIndex={0} role="group" aria-label="Варианты ответа">{options.map((o,i)=><label key={o.id}><input type={t.type==='single'?'radio':'checkbox'} name={t.id} checked={Array.isArray(a?.draft)&&a.draft.includes(o.id)} disabled={disabled} onChange={()=>choice(o.id)}/><b>{String.fromCharCode(1040+i)}</b><span>{o.text}</span></label>)}</div>}
 {t.type==='short'&&<label className="short-field">Ваш ответ<input aria-label="Краткий ответ" value={typeof a?.draft==='string'?a.draft:''} disabled={disabled} autoComplete="off" onChange={e=>ctx.change(t,e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();void ctx.submit(t)}}}/></label>}
 {t.type==='matching'&&<div className="matching-fields" tabIndex={0} role="group" aria-label="Пары для сопоставления">{t.items?.map(item=><label key={item.id}><span>{item.text}</span><select aria-label={`Соответствие: ${item.text}`} disabled={disabled} value={a?.draft&&typeof a.draft==='object'&&!Array.isArray(a.draft)?a.draft[item.id]||'':''} onChange={e=>ctx.change(t,{...(typeof a?.draft==='object'&&!Array.isArray(a.draft)?a.draft:{}),[item.id]:e.target.value})}><option value="">Выберите соответствие</option>{options.map(o=><option value={o.id} key={o.id}>{o.text}</option>)}</select></label>)}</div>}
 <div className="task-actions">{ctx.readonly?<>{done&&<span className={`task-status ${a!.result!.status}`}>{a!.result!.status==='correct'?'Правильно':'Есть ошибка'} · {a!.result!.score.toLocaleString('ru-RU')} / 1</span>}</>:!done?<button className="button primary" disabled={ctx.busy===t.id} onClick={()=>void ctx.submit(t)}>{ctx.busy===t.id?'Проверяем…':'Проверить'}</button>:<><span className={`task-status ${a!.result!.status}`} role="status">{a!.result!.status==='correct'?'Правильно':'Есть ошибка'} · {a!.result!.score.toLocaleString('ru-RU')} / 1</span><button className="button ghost" onClick={()=>ctx.reveal(t,true)}>Разбор ответа</button><button className="button ghost" onClick={()=>ctx.retry(t)}>Ещё попытка</button></>}{ctx.error&&<span role="alert" className="task-error">{ctx.error}</span>}</div>
 {show&&a?.result&&ctx.readonly&&<aside className="audience-answer"><strong>Разбор ответа</strong><p>{a.result.solution}</p><p>{a.result.explanation}</p></aside>}
 {show&&a?.result&&!ctx.readonly&&<Modal title="Разбор ответа" onClose={()=>ctx.reveal(t,false)}><p>{a.result.explanation}</p><h3>Правильный ответ</h3><p className="preserve-lines">{a.result.solution}</p>{ctx.keys[t.id]?.optionExplanations&&<ul>{Object.entries(ctx.keys[t.id].optionExplanations!).map(([id,text])=><li key={id}><strong>{t.options?.find(o=>o.id===id)?.text}:</strong> {text}</li>)}</ul>}</Modal>}
 </section>
}
export function AssessmentResults({lecture,onGo}:{lecture:Lecture;onGo:(index:number)=>void}){
 const ctx=useContext(AssessmentContext)!;const [confirm,setConfirm]=useState(false)
 let question={id:'lecture',title:'Задания лекции',label:''}
 const tasks=lecture.slides.flatMap((s,index)=>{if(s.kind==='section')question={id:s.id,title:s.title,label:s.kicker};return s.task?[{task:s.task,index,question}]:[]})
 const groups=[...new Map(tasks.map(x=>[x.question.id,x.question])).values()]
 const correct=tasks.filter(x=>ctx.attempts[x.task.id]?.result?.status==='correct').length
 const wrong=tasks.filter(x=>ctx.attempts[x.task.id]?.result?.status==='incorrect').length
 const checked=correct+wrong,score=tasks.reduce((sum,x)=>sum+(ctx.attempts[x.task.id]?.result?.score||0),0)
 const pending=tasks.find(x=>!ctx.attempts[x.task.id]?.result)
 const types={single:'Один ответ',multiple:'Несколько ответов',short:'Краткий ответ',matching:'Сопоставление'}
 return <div className="assessment-overview">
  <div className="assessment-progress"><div><span className="assessment-eyebrow">Прогресс по лекции</span><h3>{checked?`Проверено ${checked} из ${tasks.length}`:'Начните с первого задания'}</h3><p>{checked?`Правильно: ${correct} · С ошибкой: ${wrong} · Осталось: ${tasks.length-checked}`:`${groups.length} вопросов · ${tasks.length} задания. Результаты появятся после проверки ответа.`}</p></div><div className="assessment-score"><strong>{score.toLocaleString('ru-RU')}</strong><span>из {tasks.length} баллов</span></div><progress aria-label="Проверенные задания" value={checked} max={tasks.length}/>{pending&&<button className="button primary" onClick={()=>onGo(pending.index)}>{checked?'Продолжить самопроверку':'Начать самопроверку'} →</button>}</div>
  <div className="assessment-groups">{groups.map(group=>{const list=tasks.filter(x=>x.question.id===group.id),done=list.filter(x=>ctx.attempts[x.task.id]?.result).length,errors=list.filter(x=>ctx.attempts[x.task.id]?.result?.status==='incorrect').length,points=list.reduce((sum,x)=>sum+(ctx.attempts[x.task.id]?.result?.score||0),0);return <details className="assessment-group" key={group.id}><summary><span className="assessment-group-title"><small>{group.label||'Самопроверка'}</small><strong>{group.title}</strong></span><span className="assessment-group-status"><b>{points.toLocaleString('ru-RU')} / {list.length}</b><span>{done?`Проверено ${done} из ${list.length}${errors?` · С ошибкой: ${errors}`:''}`:'Не начато'}</span></span></summary><ol className="assessment-task-list">{list.map(({task:t,index},i)=>{const a=ctx.attempts[t.id];return <li key={t.id}><div className="assessment-task-heading"><span>{i+1}. {types[t.type]}</span><span className={`assessment-badge ${a?.result?.status||'pending'}`}>{!a?.result?'Не проверено':a.result.status==='correct'?'Правильно':'Есть ошибка'}</span></div><p>{t.prompt}</p><button className="button secondary" onClick={()=>onGo(index)}>{a?.result?'Открыть задание':'Ответить'} →</button>{a?.result&&<details className="assessment-answer"><summary>Ответ и объяснение · {a.result.score.toLocaleString('ru-RU')} / 1</summary><p><strong>Ваш ответ:</strong> {formatAnswer(t,a.submitted!)}</p><p><strong>Правильный ответ:</strong></p><p className="preserve-lines">{a.result.solution}</p><p>{a.result.explanation}</p></details>}</li>})}</ol></details>})}</div>
  <p className="assessment-scoring">За задание — до 1 балла. В сопоставлении балл складывается из верных пар.</p>
  {confirm?<div className="dialog-actions"><span>Сбросить все попытки курса на этом устройстве?</span><button className="button primary" onClick={()=>{ctx.reset();setConfirm(false)}}>Сбросить</button><button className="button ghost" onClick={()=>setConfirm(false)}>Отмена</button></div>:<button className="button ghost assessment-reset" onClick={()=>setConfirm(true)}>Сбросить результаты курса</button>}
 </div>
}
function formatAnswer(t:Task,a:Answer){if(typeof a==='string')return a;if(Array.isArray(a))return a.map(id=>t.options?.find(o=>o.id===id)?.text||id).join('; ');return Object.entries(a).map(([id,x])=>`${t.items?.find(o=>o.id===id)?.text}: ${t.options?.find(o=>o.id===x)?.text||'—'}`).join('; ')}


export function AssessmentSync({task,onChange}:{task?:Task;onChange:(value:Record<string,Attempt>)=>void}){const ctx=useContext(AssessmentContext)!;const attempt=task?ctx.attempts[task.id]:undefined;useEffect(()=>{onChange(task&&attempt?{[task.id]:attempt}:{})},[task?.id,attempt,onChange]);return null}
